    }
    bridges.each { bridge ->
        def id = bridge.iface.toString()
        emitState(id, bridge)
        pveEmit(id, 'Ports', [bridge.bridge_ports, bridge.ovs_ports].findAll { it }.join(' ').tokenize(' ').size())
